def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 90:
                    aggressive_count += 1
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        bid = max(78.0, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        if tight_supply:
            bid = max(58.0, avg_prev + 4.0)
        else:
            bid = max(46.0, avg_prev + 2.0)
    else:
        if loose_supply:
            bid = 16.0
        elif tight_supply:
            bid = max(34.0, min(62.0, avg_prev + 1.5))
        else:
            bid = max(24.0, min(48.0, avg_prev * 0.7 + 3.0))

    if aggressive_count >= 1 and hp > 4 and no_water == 0:
        bid = min(bid, 28.0 if not tight_supply else 38.0)

    if desperate_count >= 2 and (hp <= 4 or tight_supply):
        bid = max(bid, 55.0)

    if highest_prev >= 120 and hp > 4 and no_water == 0:
        bid = min(bid, 26.0 if loose_supply else 34.0)

    bid = min(bid, budget)
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents, but ignore Cindy if she is too high
    yesterday_bids = []
    for opp_id, opp in alive.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        # no info, default moderate
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.85)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

    # Separate high and low bidders
    high_bids = [b for b in yesterday_bids if b >= 100]
    low_bids = [b for b in yesterday_bids if b < 100]

    if high_bids:
        # Avoid high competition: bid around 70th percentile of low bids or moderate
        if low_bids:
            target = max(low_bids) * 0.85 + 2
        else:
            target = DAILY_SALARY * 0.5
    else:
        # No high bidders, bid slightly above max yesterday among low bids
        target = max(yesterday_bids) + 2.5

    # Scale by urgency
    if my_status['hp'] <= 2:
        target = max(target, DAILY_SALARY * 0.75)
    elif my_status['hp'] <= 4:
        target = max(target, DAILY_SALARY * 0.5)
    else:
        target = min(target, DAILY_SALARY * 0.6)

    # Ensure within budget and reasonable
    bid = max(DAILY_SALARY * 0.35, min(my_status['budget'], target, DAILY_SALARY * 0.95))
    return bid
